INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (300, 1, 'Números del 1 al 10', '数字', 'Cuenta del 1 al 10 en japonés.', 9, 4, 1, '{"activities":[{"id":"u1l4a1","kind":"intro_vocab","word":"一","reading":"いち","meaning":"uno","example":"一"},{"id":"u1l4a2","kind":"intro_vocab","word":"二","reading":"に","meaning":"dos","example":"二"},{"id":"u1l4a3","kind":"intro_vocab","word":"三","reading":"さん","meaning":"tres","example":"三"},{"id":"u1l4a4","kind":"intro_vocab","word":"四","reading":"よん／し","meaning":"cuatro","example":"四"},{"id":"u1l4a5","kind":"intro_vocab","word":"五","reading":"ご","meaning":"cinco","example":"五"},{"id":"u1l4q1","kind":"quiz","prompt":"¿Cómo se dice ''tres''?","options":["さん","に","ご"],"correctIndex":0,"explanation":"三 = さん = tres."},{"id":"u1l4q2","kind":"quiz","prompt":"¿Qué número es 五?","options":["cinco","cuatro","dos"],"correctIndex":0,"explanation":"五 = ご = cinco."},{"id":"u1l4s1","kind":"speaking","textJp":"いち、に、さん","reading":"いち、に、さん","meaning":"uno, dos, tres","voice":"Kyoko"},{"id":"u1l4sum","kind":"summary","learned":["一 (いち)","二 (に)","三 (さん)","四 (よん)","五 (ご)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (301, 1, 'Números del 6 al 10', '数字 2', 'Completa la cuenta hasta diez.', 9, 5, 1, '{"activities":[{"id":"u1l5a1","kind":"intro_vocab","word":"六","reading":"ろく","meaning":"seis","example":"六"},{"id":"u1l5a2","kind":"intro_vocab","word":"七","reading":"なな／しち","meaning":"siete","example":"七"},{"id":"u1l5a3","kind":"intro_vocab","word":"八","reading":"はち","meaning":"ocho","example":"八"},{"id":"u1l5a4","kind":"intro_vocab","word":"九","reading":"きゅう／く","meaning":"nueve","example":"九"},{"id":"u1l5a5","kind":"intro_vocab","word":"十","reading":"じゅう","meaning":"diez","example":"十"},{"id":"u1l5q1","kind":"quiz","prompt":"¿Cómo se dice ''diez''?","options":["じゅう","はち","ろく"],"correctIndex":0,"explanation":"十 = じゅう = diez."},{"id":"u1l5q2","kind":"quiz","prompt":"¿Qué número es 八?","options":["ocho","seis","nueve"],"correctIndex":0,"explanation":"八 = はち = ocho."},{"id":"u1l5s1","kind":"speaking","textJp":"はち、きゅう、じゅう","reading":"はち、きゅう、じゅう","meaning":"ocho, nueve, diez","voice":"Otoya"},{"id":"u1l5sum","kind":"summary","learned":["六 (ろく)","七 (なな)","八 (はち)","九 (きゅう)","十 (じゅう)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (302, 1, 'Esto, eso, aquello', 'これ・それ・あれ', 'Señala cosas: これ / それ / あれ.', 9, 6, 1, '{"activities":[{"id":"u1l6a1","kind":"intro_vocab","word":"これ","reading":"これ","meaning":"esto (cerca de mí)","example":"これは本です。"},{"id":"u1l6a2","kind":"intro_vocab","word":"それ","reading":"それ","meaning":"eso (cerca de ti)","example":"それはペンです。"},{"id":"u1l6a3","kind":"intro_vocab","word":"あれ","reading":"あれ","meaning":"aquello (lejos)","example":"あれは車です。"},{"id":"u1l6g1","kind":"intro_grammar","title":"これは〜です","pattern":"これは N です","explanation":"Para decir ''esto es N''.","example":{"jp":"これは本です。","reading":"これはほんです","meaning":"Esto es un libro."}},{"id":"u1l6q1","kind":"quiz","prompt":"Para algo lejos de ambos usas…","options":["あれ","これ","それ"],"correctIndex":0,"explanation":"あれ = aquello (lejos)."},{"id":"u1l6w1","kind":"write_sentence","prompt":"Escribe: ''Esto es un libro.''","hint":"これ + は + 本 + です","accepted":["これは本です","これは本です。","これはほんです"],"explanation":"これ = esto; 本 (ほん) = libro."},{"id":"u1l6sum","kind":"summary","learned":["これ (esto)","それ (eso)","あれ (aquello)","これは N です"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (303, 1, 'Sí, no y preguntas', 'はい・いいえ', 'Responde sí/no y haz preguntas con か.', 9, 7, 1, '{"activities":[{"id":"u1l7a1","kind":"intro_vocab","word":"はい","reading":"はい","meaning":"sí","example":"はい、そうです。"},{"id":"u1l7a2","kind":"intro_vocab","word":"いいえ","reading":"いいえ","meaning":"no","example":"いいえ、ちがいます。"},{"id":"u1l7g1","kind":"intro_grammar","title":"〜か","pattern":"… です か","explanation":"Añade か al final para preguntar.","example":{"jp":"学生ですか。","reading":"がくせいですか","meaning":"¿Eres estudiante?"}},{"id":"u1l7q1","kind":"quiz","prompt":"¿Cómo conviertes ''です'' en pregunta?","options":["agregar か","agregar ね","agregar を"],"correctIndex":0,"explanation":"か al final hace la pregunta."},{"id":"u1l7L1","kind":"listening","textJp":"がくせいですか。","voice":"Kyoko","prompt":"¿Qué te preguntan?","options":["¿Eres estudiante?","¿Dónde estás?","¿Qué comes?"],"correctIndex":0,"explanation":"学生 = estudiante; か = pregunta."},{"id":"u1l7s1","kind":"speaking","textJp":"はい、学生です。","reading":"はい、がくせいです","meaning":"Sí, soy estudiante.","voice":"Otoya"},{"id":"u1l7sum","kind":"summary","learned":["はい (sí)","いいえ (no)","〜か (pregunta)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (304, 1, 'Mi familia', '家族', 'Habla de tu familia cercana.', 9, 8, 1, '{"activities":[{"id":"u1l8a1","kind":"intro_vocab","word":"父","reading":"ちち","meaning":"(mi) padre","example":"父は先生です。"},{"id":"u1l8a2","kind":"intro_vocab","word":"母","reading":"はは","meaning":"(mi) madre","example":"母は元気です。"},{"id":"u1l8a3","kind":"intro_vocab","word":"家族","reading":"かぞく","meaning":"familia","example":"家族は四人です。"},{"id":"u1l8q1","kind":"quiz","prompt":"¿Cómo dices ''(mi) madre''?","options":["はは","ちち","あね"],"correctIndex":0,"explanation":"母 = はは = mi madre."},{"id":"u1l8w1","kind":"write_sentence","prompt":"Escribe: ''Mi padre es profesor.''","hint":"父 + は + 先生 + です","accepted":["父は先生です","父は先生です。","ちちはせんせいです"],"explanation":"父 (ちち) = mi padre; 先生 (せんせい) = profesor."},{"id":"u1l8s1","kind":"speaking","textJp":"これは私の家族です。","reading":"これはわたしのかぞくです","meaning":"Esta es mi familia.","voice":"Kyoko"},{"id":"u1l8sum","kind":"summary","learned":["父 (ちち)","母 (はは)","家族 (かぞく)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (305, 1, 'Colores básicos', '色', 'Di los colores más comunes.', 9, 9, 1, '{"activities":[{"id":"u1l9a1","kind":"intro_vocab","word":"赤","reading":"あか","meaning":"rojo","example":"赤いりんご"},{"id":"u1l9a2","kind":"intro_vocab","word":"青","reading":"あお","meaning":"azul","example":"青い空"},{"id":"u1l9a3","kind":"intro_vocab","word":"白","reading":"しろ","meaning":"blanco","example":"白い雪"},{"id":"u1l9a4","kind":"intro_vocab","word":"黒","reading":"くろ","meaning":"negro","example":"黒い猫"},{"id":"u1l9q1","kind":"quiz","prompt":"¿Qué color es 青?","options":["azul","rojo","negro"],"correctIndex":0,"explanation":"青 = あお = azul."},{"id":"u1l9q2","kind":"quiz","prompt":"''Blanco'' es…","options":["しろ","くろ","あか"],"correctIndex":0,"explanation":"白 = しろ = blanco."},{"id":"u1l9s1","kind":"speaking","textJp":"赤、青、白、黒","reading":"あか、あお、しろ、くろ","meaning":"rojo, azul, blanco, negro","voice":"Otoya"},{"id":"u1l9sum","kind":"summary","learned":["赤 (あか)","青 (あお)","白 (しろ)","黒 (くろ)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (306, 1, 'Los días de la semana', '曜日', 'Nombra los días de la semana.', 9, 10, 1, '{"activities":[{"id":"u1l10a1","kind":"intro_vocab","word":"月曜日","reading":"げつようび","meaning":"lunes","example":"月曜日"},{"id":"u1l10a2","kind":"intro_vocab","word":"火曜日","reading":"かようび","meaning":"martes","example":"火曜日"},{"id":"u1l10a3","kind":"intro_vocab","word":"水曜日","reading":"すいようび","meaning":"miércoles","example":"水曜日"},{"id":"u1l10a4","kind":"intro_vocab","word":"土曜日","reading":"どようび","meaning":"sábado","example":"土曜日"},{"id":"u1l10a5","kind":"intro_vocab","word":"日曜日","reading":"にちようび","meaning":"domingo","example":"日曜日"},{"id":"u1l10q1","kind":"quiz","prompt":"¿Qué día es 日曜日?","options":["domingo","lunes","sábado"],"correctIndex":0,"explanation":"日曜日 = にちようび = domingo."},{"id":"u1l10w1","kind":"write_sentence","prompt":"Escribe ''lunes'' en japonés.","hint":"月 + 曜日","accepted":["月曜日","げつようび"],"explanation":"月曜日 (げつようび) = lunes."},{"id":"u1l10sum","kind":"summary","learned":["月曜日 (lunes)","水曜日 (miércoles)","土曜日 (sábado)","日曜日 (domingo)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (310, 2, '¿Qué hora es?', '今、何時？', 'Pregunta y di la hora.', 9, 3, 1, '{"activities":[{"id":"u2l3a1","kind":"intro_vocab","word":"今","reading":"いま","meaning":"ahora","example":"今、何時ですか。"},{"id":"u2l3a2","kind":"intro_vocab","word":"時","reading":"じ","meaning":"hora(s) / en punto","example":"三時"},{"id":"u2l3g1","kind":"intro_grammar","title":"何時ですか","pattern":"今 何時 ですか","explanation":"Para preguntar la hora.","example":{"jp":"今、何時ですか。","reading":"いま、なんじですか","meaning":"¿Qué hora es ahora?"}},{"id":"u2l3q1","kind":"quiz","prompt":"¿Cómo preguntas la hora?","options":["今、何時ですか。","今、何ですか。","今、どこですか。"],"correctIndex":0,"explanation":"何時 (なんじ) = qué hora."},{"id":"u2l3L1","kind":"listening","textJp":"三時です。","voice":"Kyoko","prompt":"¿Qué hora dicen?","options":["Las 3","Las 5","Las 9"],"correctIndex":0,"explanation":"三 = さん = 3, 時 = じ."},{"id":"u2l3s1","kind":"speaking","textJp":"今、何時ですか。","reading":"いま、なんじですか","meaning":"¿Qué hora es ahora?","voice":"Otoya"},{"id":"u2l3sum","kind":"summary","learned":["今 (いま)","時 (じ)","何時ですか (¿qué hora es?)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (311, 2, 'En casa', '家で', 'Objetos y lugares de la casa.', 9, 4, 1, '{"activities":[{"id":"u2l4a1","kind":"intro_vocab","word":"家","reading":"いえ","meaning":"casa","example":"私の家"},{"id":"u2l4a2","kind":"intro_vocab","word":"部屋","reading":"へや","meaning":"habitación","example":"部屋は広いです。"},{"id":"u2l4a3","kind":"intro_vocab","word":"テーブル","reading":"てーぶる","meaning":"mesa","example":"テーブルの上"},{"id":"u2l4q1","kind":"quiz","prompt":"¿Qué significa 部屋?","options":["habitación","casa","mesa"],"correctIndex":0,"explanation":"部屋 = へや = habitación."},{"id":"u2l4w1","kind":"write_sentence","prompt":"Escribe: ''Esta es mi casa.''","hint":"これ + は + 私の家 + です","accepted":["これは私の家です","これは私の家です。","これはわたしのいえです"],"explanation":"家 (いえ) = casa."},{"id":"u2l4s1","kind":"speaking","textJp":"部屋はきれいです。","reading":"へやはきれいです","meaning":"La habitación está limpia.","voice":"Kyoko"},{"id":"u2l4sum","kind":"summary","learned":["家 (いえ)","部屋 (へや)","テーブル (mesa)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (312, 2, 'Comida y bebida', '食べ物・飲み物', 'Pide y nombra comida y bebida.', 9, 5, 1, '{"activities":[{"id":"u2l5a1","kind":"intro_vocab","word":"ご飯","reading":"ごはん","meaning":"arroz / comida","example":"ご飯を食べます。"},{"id":"u2l5a2","kind":"intro_vocab","word":"水","reading":"みず","meaning":"agua","example":"水を飲みます。"},{"id":"u2l5a3","kind":"intro_vocab","word":"お茶","reading":"おちゃ","meaning":"té","example":"お茶をください。"},{"id":"u2l5g1","kind":"intro_grammar","title":"〜を食べます／飲みます","pattern":"N を 食べます／飲みます","explanation":"Comer/beber algo.","example":{"jp":"ご飯を食べます。","reading":"ごはんをたべます","meaning":"Como arroz."}},{"id":"u2l5q1","kind":"quiz","prompt":"''Bebo agua'' es…","options":["水を飲みます。","水を食べます。","水をします。"],"correctIndex":0,"explanation":"飲みます = beber."},{"id":"u2l5w1","kind":"write_sentence","prompt":"Escribe: ''Como arroz.''","hint":"ご飯 + を + 食べます","accepted":["ご飯を食べます","ご飯を食べます。","ごはんをたべます"],"explanation":"食べます = comer."},{"id":"u2l5sum","kind":"summary","learned":["ご飯 (ごはん)","水 (みず)","お茶 (おちゃ)","〜を食べます／飲みます"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (313, 2, 'Adjetivos い', 'い形容詞', 'Describe con adjetivos い.', 9, 6, 1, '{"activities":[{"id":"u2l6a1","kind":"intro_vocab","word":"大きい","reading":"おおきい","meaning":"grande","example":"大きい家"},{"id":"u2l6a2","kind":"intro_vocab","word":"小さい","reading":"ちいさい","meaning":"pequeño","example":"小さい猫"},{"id":"u2l6a3","kind":"intro_vocab","word":"新しい","reading":"あたらしい","meaning":"nuevo","example":"新しい車"},{"id":"u2l6g1","kind":"intro_grammar","title":"い形容詞 + です","pattern":"Adj-い + です","explanation":"Los adjetivos い describen cosas: ''es ~''.","example":{"jp":"車は新しいです。","reading":"くるまはあたらしいです","meaning":"El coche es nuevo."}},{"id":"u2l6q1","kind":"quiz","prompt":"¿Qué significa 小さい?","options":["pequeño","grande","nuevo"],"correctIndex":0,"explanation":"小さい = ちいさい = pequeño."},{"id":"u2l6s1","kind":"speaking","textJp":"この家は大きいです。","reading":"このいえはおおきいです","meaning":"Esta casa es grande.","voice":"Otoya"},{"id":"u2l6sum","kind":"summary","learned":["大きい (おおきい)","小さい (ちいさい)","新しい (あたらしい)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (314, 2, 'El clima', '天気', 'Habla del clima de hoy.', 9, 7, 1, '{"activities":[{"id":"u2l7a1","kind":"intro_vocab","word":"天気","reading":"てんき","meaning":"clima / tiempo","example":"今日はいい天気です。"},{"id":"u2l7a2","kind":"intro_vocab","word":"雨","reading":"あめ","meaning":"lluvia","example":"雨が降ります。"},{"id":"u2l7a3","kind":"intro_vocab","word":"暑い","reading":"あつい","meaning":"caluroso","example":"今日は暑いです。"},{"id":"u2l7a4","kind":"intro_vocab","word":"寒い","reading":"さむい","meaning":"frío","example":"冬は寒いです。"},{"id":"u2l7q1","kind":"quiz","prompt":"¿Qué significa 暑い?","options":["caluroso","frío","lluvia"],"correctIndex":0,"explanation":"暑い = あつい = caluroso."},{"id":"u2l7L1","kind":"listening","textJp":"今日は寒いです。","voice":"Kyoko","prompt":"¿Cómo está el día?","options":["Frío","Caluroso","Lluvioso"],"correctIndex":0,"explanation":"寒い = さむい = frío."},{"id":"u2l7sum","kind":"summary","learned":["天気 (てんき)","雨 (あめ)","暑い (あつい)","寒い (さむい)"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (315, 2, 'Mi rutina diaria', '毎日', 'Cuenta lo que haces cada día.', 9, 8, 1, '{"activities":[{"id":"u2l8a1","kind":"intro_vocab","word":"起きます","reading":"おきます","meaning":"levantarse","example":"七時に起きます。"},{"id":"u2l8a2","kind":"intro_vocab","word":"寝ます","reading":"ねます","meaning":"dormir","example":"十一時に寝ます。"},{"id":"u2l8a3","kind":"intro_vocab","word":"毎日","reading":"まいにち","meaning":"todos los días","example":"毎日勉強します。"},{"id":"u2l8g1","kind":"intro_grammar","title":"時間 + に","pattern":"（時）に + verbo","explanation":"Marca la hora a la que pasa algo.","example":{"jp":"七時に起きます。","reading":"しちじにおきます","meaning":"Me levanto a las 7."}},{"id":"u2l8q1","kind":"quiz","prompt":"''Me levanto'' es…","options":["起きます","寝ます","食べます"],"correctIndex":0,"explanation":"起きます = levantarse."},{"id":"u2l8w1","kind":"write_sentence","prompt":"Escribe: ''Me levanto a las 7.''","hint":"七時 + に + 起きます","accepted":["七時に起きます","七時に起きます。","しちじにおきます"],"explanation":"に marca la hora; 起きます = levantarse."},{"id":"u2l8sum","kind":"summary","learned":["起きます (levantarse)","寝ます (dormir)","毎日 (まいにち)","（時）に"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (316, 2, 'En la ciudad', '町で', 'Lugares de la ciudad y cómo llegar.', 9, 9, 1, '{"activities":[{"id":"u2l9a1","kind":"intro_vocab","word":"店","reading":"みせ","meaning":"tienda","example":"店に行きます。"},{"id":"u2l9a2","kind":"intro_vocab","word":"病院","reading":"びょういん","meaning":"hospital","example":"病院はどこですか。"},{"id":"u2l9a3","kind":"intro_vocab","word":"銀行","reading":"ぎんこう","meaning":"banco","example":"銀行へ行きます。"},{"id":"u2l9g1","kind":"intro_grammar","title":"〜へ行きます","pattern":"場所 へ 行きます","explanation":"Ir a un lugar.","example":{"jp":"学校へ行きます。","reading":"がっこうへいきます","meaning":"Voy a la escuela."}},{"id":"u2l9q1","kind":"quiz","prompt":"¿Qué significa 病院?","options":["hospital","tienda","banco"],"correctIndex":0,"explanation":"病院 = びょういん = hospital."},{"id":"u2l9s1","kind":"speaking","textJp":"店はどこですか。","reading":"みせはどこですか","meaning":"¿Dónde está la tienda?","voice":"Otoya"},{"id":"u2l9sum","kind":"summary","learned":["店 (みせ)","病院 (びょういん)","銀行 (ぎんこう)","〜へ行きます"]}]}');
INSERT OR REPLACE INTO lessons (id, unit_id, title, jp_title, summary, duration_minutes, ordering, is_seed, activities_json) VALUES (317, 2, 'Gustos: 好き', '好きなもの', 'Di lo que te gusta con 好き.', 9, 10, 1, '{"activities":[{"id":"u2l10a1","kind":"intro_vocab","word":"好き","reading":"すき","meaning":"gustar / favorito","example":"日本語が好きです。"},{"id":"u2l10a2","kind":"intro_vocab","word":"音楽","reading":"おんがく","meaning":"música","example":"音楽が好きです。"},{"id":"u2l10g1","kind":"intro_grammar","title":"〜が好きです","pattern":"N が 好きです","explanation":"Para decir que algo te gusta.","example":{"jp":"日本語が好きです。","reading":"にほんごがすきです","meaning":"Me gusta el japonés."}},{"id":"u2l10q1","kind":"quiz","prompt":"''Me gusta la música'' es…","options":["音楽が好きです。","音楽を食べます。","音楽はどこですか。"],"correctIndex":0,"explanation":"〜が好きです = me gusta ~."},{"id":"u2l10w1","kind":"write_sentence","prompt":"Escribe: ''Me gusta el japonés.''","hint":"日本語 + が + 好き + です","accepted":["日本語が好きです","日本語が好きです。","にほんごがすきです"],"explanation":"が好きです = me gusta."},{"id":"u2l10s1","kind":"speaking","textJp":"私は音楽が好きです。","reading":"わたしはおんがくがすきです","meaning":"Me gusta la música.","voice":"Kyoko"},{"id":"u2l10sum","kind":"summary","learned":["好き (すき)","音楽 (おんがく)","〜が好きです"]}]}');
